//! Protobuf messages exchanged with the tag monitor, with reflection.
//!
//! Generated by `build.rs` from `proto/tag.proto` and `proto/tagdata.proto`,
//! the same definitions the C++ host tools and the firmware's nanopb code
//! use. A request is a [`Req`] whose `payload` selects the operation; every
//! reply is an [`Ack`] with an [`ack::Err`] code and an optional payload.
//!
//! Every message implements [`prost_reflect::ReflectMessage`] against
//! [`DESCRIPTOR_POOL`], which backs the C++-compatible text format and JSON
//! helpers below: [`debug_string`], [`short_debug_string`], [`to_json`] and
//! [`from_json`].

#![allow(clippy::all, missing_docs)]

use std::sync::LazyLock;

use prost_reflect::{
    DescriptorPool, DeserializeOptions, DynamicMessage, ReflectMessage, SerializeOptions,
};

include!(concat!(env!("OUT_DIR"), "/_.rs"));

/// Descriptors of every message and enum in `tag.proto` and `tagdata.proto`.
pub static DESCRIPTOR_POOL: LazyLock<DescriptorPool> = LazyLock::new(|| {
    DescriptorPool::decode(
        include_bytes!(concat!(env!("OUT_DIR"), "/file_descriptor_set.bin")).as_ref(),
    )
    .expect("embedded file descriptor set decodes")
});

impl Ack {
    /// The firmware's error text, or `""` when the payload is not
    /// `error_message`. Matches the C++ `Ack::error_message()` accessor,
    /// which returns an empty string for an unset oneof member.
    pub fn error_message(&self) -> &str {
        match &self.payload {
            Some(ack::Payload::ErrorMessage(message)) => message,
            _ => "",
        }
    }
}

/// The message in protobuf text format, one field per line, as the C++
/// `Message::DebugString()` prints it; see [`crate::textformat`].
pub fn debug_string<M: ReflectMessage>(msg: &M) -> String {
    crate::textformat::debug_string(msg)
}

/// The message in protobuf text format on one line, as the C++
/// `Message::ShortDebugString()` prints it.
pub fn short_debug_string<M: ReflectMessage>(msg: &M) -> String {
    crate::textformat::short_debug_string(msg)
}

/// The message as compact proto3 JSON with `.proto` field names, the options
/// tagcore uses when it stores these messages: no whitespace, fields at their
/// default omitted, enums by name, 64-bit integers as strings.
pub fn to_json<M: ReflectMessage>(msg: &M) -> String {
    let dynamic = msg.transcode_to_dynamic();
    let mut out = serde_json::Serializer::with_formatter(Vec::new(), CppFloats);
    dynamic
        .serialize_with_options(
            &mut out,
            &SerializeOptions::new().use_proto_field_name(true),
        )
        .expect("a message always serializes to JSON");
    String::from_utf8(out.into_inner()).expect("JSON is UTF-8")
}

/// Compact JSON with floats written as the C++ `json_util` writes them
/// (`SimpleFtoa`/`SimpleDtoa`: `3`, not `3.0`). Non-finite values never
/// reach it; proto3 JSON spells those as strings.
struct CppFloats;

impl serde_json::ser::Formatter for CppFloats {
    fn write_f32<W: ?Sized + std::io::Write>(&mut self, w: &mut W, v: f32) -> std::io::Result<()> {
        let text =
            crate::textformat::format_g(f64::from(v), 6, 9, |s| s.parse::<f32>().ok() == Some(v));
        w.write_all(text.as_bytes())
    }

    fn write_f64<W: ?Sized + std::io::Write>(&mut self, w: &mut W, v: f64) -> std::io::Result<()> {
        let text = crate::textformat::format_g(v, 15, 17, |s| s.parse::<f64>().ok() == Some(v));
        w.write_all(text.as_bytes())
    }
}

/// Parses proto3 JSON into a message, as the C++ `JsonStringToMessage` does
/// with default options: `.proto` or lowerCamelCase field names, enums by
/// name or number, and unknown fields rejected.
///
/// Returns the parse error as text on failure.
pub fn from_json<M: ReflectMessage + Default>(text: &str) -> Result<M, String> {
    let descriptor = M::default().descriptor();
    let mut de = serde_json::Deserializer::from_str(text);
    let dynamic =
        DynamicMessage::deserialize_with_options(descriptor, &mut de, &DeserializeOptions::new())
            .map_err(|e| e.to_string())?;
    de.end().map_err(|e| e.to_string())?;
    dynamic.transcode_to::<M>().map_err(|e| e.to_string())
}

#[cfg(test)]
mod tests {
    use super::*;

    fn sample_config() -> Config {
        Config {
            tag_type: TagType::BittagLe as i32,
            active_interval: Some(config::Interval {
                start_epoch: 0,
                end_epoch: 2147483647,
            }),
            hibernate: vec![config::Interval::default(); 2],
            bittag_log: BitTagLogFmt::BittagBitsperfivemin as i32,
            ..Default::default()
        }
    }

    #[test]
    fn debug_string_matches_cpp_layout() {
        assert_eq!(
            debug_string(&sample_config()),
            "tag_type: BITTAG_LE\nactive_interval {\n  end_epoch: 2147483647\n}\nhibernate {\n}\nhibernate {\n}\nbittag_log: BITTAG_BITSPERFIVEMIN\n"
        );
    }

    #[test]
    fn json_uses_proto_names_and_round_trips() {
        let config = sample_config();
        let json = to_json(&config);
        assert_eq!(
            json,
            r#"{"tag_type":"BITTAG_LE","active_interval":{"end_epoch":2147483647},"hibernate":[{},{}],"bittag_log":"BITTAG_BITSPERFIVEMIN"}"#
        );
        assert_eq!(from_json::<Config>(&json).unwrap(), config);
    }

    #[test]
    fn json_floats_print_as_cpp_does() {
        let status = Status {
            voltage: 3.0,
            temperature: 23.6,
            ..Default::default()
        };
        assert_eq!(to_json(&status), r#"{"voltage":3,"temperature":23.6}"#);
    }

    #[test]
    fn json_accepts_camel_case_and_rejects_unknown_fields() {
        let c: Config = from_json(r#"{"startDelay": 5, "tag_type": "BITTAG_LE"}"#).unwrap();
        assert_eq!(c.start_delay, 5);
        assert!(from_json::<Config>(r#"{"no_such_field": 1}"#).is_err());
        assert!(from_json::<Config>(r#"{"period": 1} trailing"#).is_err());
    }
}
